INSERT INTO site_content(kind,id,data,created_at) VALUES ('news','news-1','{"id":"news-1","category":"Цифровая медицина","title":"В Казахстане формируется единая цифровая архитектура здравоохранения","description":"ЕГМИС объединит медицинские сервисы в экосистему E-Densaulyq. К декабрю 2026 года система должна стать основной платформой управления отраслью.","source":"Министерство здравоохранения РК","url":"https://www.gov.kz/memleket/entities/dsm/press/news/details/1159176?lang=ru","translationKey":"news-1"}'::jsonb,NOW()-INTERVAL '0 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('news','news-2','{"id":"news-2","category":"ОСМС","title":"Цифровизация здравоохранения и устойчивость системы ОСМС","description":"Около 17 млн казахстанцев охвачены системой ОСМС. Цифровые инструменты усиливают прозрачность, контроль качества и доступность медицинской помощи.","source":"Министерство здравоохранения РК","url":"https://www.gov.kz/memleket/entities/dsm/press/news/details/1128093?lang=ru","translationKey":"news-2"}'::jsonb,NOW()-INTERVAL '1 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('news','news-3','{"id":"news-3","category":"Здравоохранение","title":"Казахстан вошёл в топ стран по снижению смертности от хронических заболеваний","description":"Минздрав представил ключевые показатели отрасли: развитие онлайн-медицины, снижение материнской и младенческой смертности и укрепление кадрового потенциала.","source":"Министерство здравоохранения РК","url":"https://www.gov.kz/memleket/entities/dsm/press/news/details/1129298?lang=ru","translationKey":"news-3"}'::jsonb,NOW()-INTERVAL '2 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('reviews','2gis-1','{"id":"2gis-1","name":"Евгений Ким","date":"9 июля 2026","rating":5,"message":"Хорошая клиника, особенно врач-нефролог Мукашова Айжан Еркінқызы: в свой выходной приняла и выписала направление.","source":"2ГИС"}'::jsonb,NOW()-INTERVAL '0 microseconds') ON CONFLICT DO NOTHING;
