INSERT INTO site_content(kind,id,data,created_at) VALUES ('reviews','2gis-3','{"id":"2gis-3","name":"Alima Kulzhabayeva","date":"29 июня 2026","rating":5,"message":"Проходила УЗИ сердца. Хорошие, вежливые врачи. Спасибо им. Мне понравился медцентр.","source":"2ГИС"}'::jsonb,NOW()-INTERVAL '2 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('reviews','2gis-4','{"id":"2gis-4","name":"Гулбахар Сейтимбетова","date":"25 июня 2026","rating":5,"message":"Была в медцентре «Нарамед Green City». Пульмонолог Ыдырыс Ұлшай Батырханқызы очень образованная, всё проверила и объяснила. Спасибо большое ей.","source":"2ГИС"}'::jsonb,NOW()-INTERVAL '3 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('reviews','2gis-5','{"id":"2gis-5","name":"Banu Arslanova","date":"25 июня 2026","rating":5,"message":"Хорошая клиника, приняли вовремя, всё чётко объяснили.","source":"2ГИС"}'::jsonb,NOW()-INTERVAL '4 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('reviews','2gis-6','{"id":"2gis-6","name":"Barsha Tsoy","date":"22 июня 2026","rating":5,"message":"Хорошая клиника, эндокринолог Эльмира Хамитовна — топ. Анализы берут очень хорошо, без стресса и безболезненно, даже у ребёнка. Всегда чисто.","source":"2ГИС"}'::jsonb,NOW()-INTERVAL '5 microseconds') ON CONFLICT DO NOTHING;
INSERT INTO site_content(kind,id,data,created_at) VALUES ('vacancies','vacancy-1','{"id":"vacancy-1","title":"Врач общей практики","department":"Амбулаторное отделение","employment":"Полная занятость","description":"Ищем внимательного врача для амбулаторного приёма пациентов.","requirements":"Высшее медицинское образование, действующий сертификат специалиста.","contact":"+7 707 534 0824","published":true,"translationKey":"vacancy-1"}'::jsonb,NOW()-INTERVAL '0 microseconds') ON CONFLICT DO NOTHING;
